def _build(tree):
    if not tree or tree[0] is None:
        return None
    nodes = [None if v is None else {'val': v, 'left': None, 'right': None} for v in tree]
    kids = iter(range(1, len(nodes)))
    for node in nodes:
        if node is None:
            continue
        for side in ('left', 'right'):
            idx = next(kids, None)
            if idx is not None and idx < len(nodes) and nodes[idx] is not None:
                node[side] = nodes[idx]
    return nodes[0]


def max_depth(tree):
    root = _build(tree)

    def depth(node):
        if node is None:
            return 0
        return 1 + max(depth(node['left']), depth(node['right']))

    return depth(root)
